sys_script.script:
// After-update Business Rule: Create Outbound Webhook on Case Update
// Determines event priority (severity > state > reassigned > updated),
// builds payload with change data, and creates pending webhook log entries.
// Only fires for case_source='torq' cases.
(function () {
    var enabled = gs.getProperty('x_2241073_securi_0.api.enabled', 'false');
    if (enabled != 'true') return;

    // Only create webhooks for cases with case_source = 'torq'
    if (current.getValue('case_source') != 'torq') return;

    var eventName = '';
    var eventType = '';

    // Priority 1: Severity changed
    if (current.severity.changes()) {
        eventName = 'x_2241073_securi_0.case.sev_chg';
        eventType = 'case.severity_changed';
    }
    // Priority 2: State changed
    else if (current.state.changes()) {
        eventName = 'x_2241073_securi_0.case.state';
        eventType = 'case.state_changed';
    }
    // Priority 3: Assignment changed
    else if (current.assigned_to.changes() || current.assignment_group.changes()) {
        eventName = 'x_2241073_securi_0.case.assign';
        eventType = 'case.reassigned';
    }
    // Priority 4: Other tracked fields changed
    else {
        var trackedFields = ['short_description', 'description', 'category', 'subcategory', 'case_type', 'detection_source'];
        for (var i = 0; i < trackedFields.length; i++) {
            if (current[trackedFields[i]].changes()) {
                eventName = 'x_2241073_securi_0.case.update';
                eventType = 'case.updated';
                break;
            }
        }
    }

    if (!eventName) return;

    // Build change_reason from work_notes if available
    var changeReason = '';
    try {
        changeReason = current.work_notes.getJournalEntry(1) || '';
    } catch (e) {
        changeReason = '';
    }

    // Build payload
    var payload = {
        event_type: eventType,
        timestamp: new GlideDateTime().getValue(),
        case: {
            sys_id: current.getUniqueValue(),
            number: current.getValue('number'),
            short_description: current.getValue('short_description'),
            severity: current.getValue('severity'),
            state: current.getValue('state'),
            category: current.getValue('category'),
            assigned_to: current.getDisplayValue('assigned_to'),
            assignment_group: current.getDisplayValue('assignment_group'),
            sla_status: current.getValue('sla_status'),
            torq_incident_id: current.getValue('torq_incident_id'),
            api_url: gs.getProperty('glide.servlet.uri') + 'api/x_2241073_securi_0/security_case_inbound/case/' + current.getValue('number'),
        },
        changes: {},
    };

    // Add specific change data based on event type
    if (eventType == 'case.severity_changed') {
        payload.changes = {
            severity: { previous: previous.getValue('severity'), current: current.getValue('severity') },
        };
    } else if (eventType == 'case.state_changed') {
        payload.changes = {
            state: { previous: previous.getValue('state'), current: current.getValue('state') },
        };
    } else if (eventType == 'case.reassigned') {
        payload.changes = {};
        if (current.assigned_to.changes()) {
            payload.changes.assigned_to = {
                previous: previous.getDisplayValue('assigned_to'),
                current: current.getDisplayValue('assigned_to'),
            };
        }
        if (current.assignment_group.changes()) {
            payload.changes.assignment_group = {
                previous: previous.getDisplayValue('assignment_group'),
                current: current.getDisplayValue('assignment_group'),
            };
        }
    }

    if (changeReason) {
        payload.change_reason = changeReason;
    }

    // Create webhook log entry (pending for dispatcher to pick up)
    var log = new GlideRecord('x_2241073_securi_0_webhook_log');
    log.initialize();
    log.setValue('case_id', current.getUniqueValue());
    log.setValue('direction', 'outbound');
    log.setValue('endpoint_url', gs.getProperty('x_2241073_securi_0.api.url', ''));
    log.setValue('http_method', 'POST');
    log.setValue('payload', JSON.stringify(payload));
    log.setValue('status', 'pending');
    log.insert();

    // Fire the event (for downstream script actions if needed)
    gs.eventQueue(eventName, current, current.getUniqueValue(), '');
})();
